const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({
    viewport: { width: 1400, height: 1980 },
    deviceScaleFactor: 2,
  });
  const page = await context.newPage();
  page.on('console', msg => console.log('PAGE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGEERR:', err.message));
  await page.goto('file://' + path.resolve('/app/output/poster.html'), { waitUntil: 'networkidle' });
  await page.waitForFunction(() => window.__ready === true, { timeout: 60000 });
  await page.waitForTimeout(2000);
  await page.screenshot({ path: '/app/output/final_poster.png', fullPage: false, clip: { x: 0, y: 0, width: 1400, height: 1980 } });
  await browser.close();
  console.log('done');
})();

