[metadata] {"type": "update", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>IPCC AR6 Synthesis Report — Key Findings</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@500;700&display=swap');

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  width: 1400px;
  height: 1980px;
  background: linear-gradient(180deg, #060d1a 0%, #0a1628 8%, #0f1d32 50%, #0a1628 92%, #060d1a 100%);
  color: #f1f5f9;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  overflow: hidden;
  position: relative;
}

/* Subtle grid overlay */
body::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(rgba(148,163,184,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148,163,184,0.03) 1px, transparent 1px);
  background-size: 40px 40px;
  pointer-events: none;
}

.poster {
  position: relative;
  z-index: 1;
  padding: 48px 56px 40px;
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* ── HEADER ── */
.header {
  text-align: center;
  margin-bottom: 36px;
  padding-bottom: 28px;
  border-bottom: 1px solid rgba(148,163,184,0.15);
}

.header-badge {
  display: inline-block;
  background: rgba(245,158,11,0.12);
  border: 1px solid rgba(245,158,11,0.3);
  color: #fbbf24;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  padding: 6px 20px;
  border-radius: 20px;
  margin-bottom: 18px;
}

.header h1 {
  font-size: 42px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.5px;
  color: #ffffff;
  margin-bottom: 10px;
}

.header h1 span { color: #f59e0b; }

.header .subtitle {
  font-size: 15.5px;
  font-weight: 400;
  color: #94a3b8;
  line-height: 1.5;
  max-width: 900px;
  margin: 0 auto;
}

/* ── METRICS CENTERPIECE ── */
.metrics-section {
  margin-bottom: 30px;
}

.metrics-section .section-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: #64748b;
  text-align: center;
  margin-bottom: 16px;
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 12px;
}

.metric-card {
  background: linear-gradient(135deg, rgba(30,41,59,0.9), rgba(30,41,59,0.6));
  border: 1px solid rgba(71,85,105,0.4);
  border-radius: 12px;
  padding: 18px 14px 16px;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s;
}

.metric-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  border-radius: 12px 12px 0 0;
}

.metric-card:nth-child(1)::before { background: #f59e0b; }
.metric-card:nth-child(2)::before { background: #fb923c; }
.metric-card:nth-child(3)::before { background: #f97316; }
.metric-card:nth-child(4)::before { background: #ef4444; }
.metric-card:nth-child(5)::before { background: #dc2626; }
.metric-card:nth-child(6)::before { background: #ea580c; }
.metric-card:nth-child(7)::before { background: #b91c1c; }

.metric-card.highlight {
  background: linear-gradient(135deg, rgba(239,68,68,0.15), rgba(30,41,59,0.9));
  border-color: rgba(239,68,68,0.4);
  box-shadow: 0 0 30px rgba(239,68,68,0.1);
}

.metric-value {
  font-family: 'JetBrains Mono', 'Inter', monospace;
  font-size: 32px;
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 4px;
}

.metric-card:nth-child(1) .metric-value { color: #fbbf24; }
.metric-card:nth-child(2) .metric-value { color: #fb923c; }
.metric-card:nth-child(3) .metric-value { color: #f97316; }
.metric-card:nth-child(4) .metric-value { color: #ef4444; }
.metric-card:nth-child(5) .metric-value { color: #ef4444; }
.metric-card:nth-child(6) .metric-value { color: #ea580c; }
.metric-card:nth-child(7) .metric-value { color: #ef4444; }

.metric-card.highlight .metric-value {
  font-size: 34px;
}

.metric-unit {
  font-size: 12px;
  font-weight: 600;
  color: #94a3b8;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.metric-label {
  font-size: 10.5px;
  font-weight: 500;
  color: #64748b;
  line-height: 1.35;
}

/* ── CONTENT SECTIONS ── */
.content-area {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto auto;
  gap: 20px;
}

.section {
  background: rgba(30,41,59,0.5);
  border: 1px solid rgba(71,85,105,0.3);
  border-radius: 14px;
  padding: 24px;
  position: relative;
}

.section-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}

.section-number {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.section-title {
  font-size: 16px;
  font-weight: 700;
  color: #f1f5f9;
  letter-spacing: -0.2px;
}

.section-body {
  font-size: 12.5px;
  line-height: 1.6;
  color: #cbd5e1;
}

/* Section colors */
.section.observed .section-number { background: #f59e0b; }
.section.projections .section-number { background: #f97316; }
.section.risks .section-number { background: #ef4444; }
.section.mitigation .section-number { background: #14b8a6; }

/* ── OBSERVED CHANGES TABLE ── */
.indicator-table {
  width: 100%;
  margin-top: 12px;
}

.indicator-row {
  display: flex;
  align-items: center;
  padding: 9px 0;
  border-bottom: 1px solid rgba(71,85,105,0.2);
}

.indicator-row:last-child { border-bottom: none; }

.indicator-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 12px;
  flex-shrink: 0;
}

.indicator-name {
  flex: 1;
  font-size: 12px;
  color: #94a3b8;
}

.indicator-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 13px;
  font-weight: 600;
  color: #fbbf24;
  text-align: right;
}

/* ── SSP SCENARIO BARS ── */
.ssp-chart {
  margin-top: 12px;
}

.ssp-row {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.ssp-label {
  width: 78px;
  font-size: 11px;
  font-weight: 600;
  color: #94a3b8;
  flex-shrink: 0;
}

.ssp-bar-track {
  flex: 1;
  height: 26px;
  background: rgba(15,23,42,0.6);
  border-radius: 6px;
  position: relative;
  overflow: hidden;
}

.ssp-bar {
  height: 100%;
  border-radius: 6px;
  display: flex;
  align-items: center;
  padding-left: 10px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  font-weight: 600;
  color: #fff;
  min-width: 60px;
  transition: width 0.5s ease;
}

.ssp-temp {
  margin-left: auto;
  padding-right: 10px;
  font-size: 13px;
}

.ssp-desc {
  font-size: 10px;
  color: #64748b;
  margin-top: 2px;
  text-align: right;
}

/* ── RISK ITEMS ── */
.risk-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 12px;
}

.risk-item {
  background: rgba(15,23,42,0.5);
  border: 1px solid rgba(239,68,68,0.15);
  border-radius: 10px;
  padding: 14px;
}

.risk-icon {
  font-size: 20px;
  margin-bottom: 6px;
}

.risk-title {
  font-size: 12px;
  font-weight: 600;
  color: #f1f5f9;
  margin-bottom: 4px;
}

.risk-desc {
  font-size: 10.5px;
  color: #94a3b8;
  line-height: 1.4;
}

/* ── MITIGATION PATHWAYS ── */
.pathway-compare {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 12px;
}

.pathway-box {
  background: rgba(15,23,42,0.5);
  border-radius: 10px;
  padding: 16px;
  border: 1px solid;
  text-align: center;
}

.pathway-box.target-15 {
  border-color: rgba(20,184,166,0.3);
}

.pathway-box.target-2 {
  border-color: rgba(59,130,246,0.3);
}

.pathway-target {
  font-family: 'JetBrains Mono', monospace;
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 4px;
}

.pathway-box.target-15 .pathway-target { color: #14b8a6; }
.pathway-box.target-2 .pathway-target { color: #3b82f6; }

.pathway-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #64748b;
  margin-bottom: 12px;
}

.pathway-stat {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
  border-top: 1px solid rgba(71,85,105,0.2);
}

.pathway-stat-label {
  font-size: 11px;
  color: #94a3b8;
}

.pathway-stat-value {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  font-weight: 600;
  color: #f1f5f9;
}

.levers-list {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(71,85,105,0.2);
}

.lever-item {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  font-size: 11.5px;
  color: #cbd5e1;
}

.lever-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #14b8a6;
  flex-shrink: 0;
}

/* ── NARROWING WINDOW (FULL-WIDTH BOTTOM) ── */
.narrowing-window {
  grid-column: 1 / -1;
  background: linear-gradient(135deg, rgba(127,29,29,0.25), rgba(30,41,59,0.6));
  border: 1px solid rgba(239,68,68,0.25);
  border-radius: 14px;
  padding: 28px 32px;
  position: relative;
  overflow: hidden;
}

.narrowing-window::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, #f59e0b, #ef4444, #991b1b);
}

.narrowing-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.narrowing-number {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, #ef4444, #991b1b);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
}

.narrowing-title {
  font-size: 16px;
  font-weight: 700;
  color: #f1f5f9;
}

.narrowing-content {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 32px;
  align-items: center;
}

.narrowing-text {
  font-size: 13px;
  line-height: 1.65;
  color: #cbd5e1;
}

.narrowing-text strong {
  color: #fbbf24;
  font-weight: 600;
}

.narrowing-callout {
  text-align: center;
  padding: 20px 28px;
  background: rgba(15,23,42,0.5);
  border-radius: 12px;
  border: 1px solid rgba(239,68,68,0.2);
}

.narrowing-callout-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #64748b;
  margin-bottom: 6px;
}

.narrowing-callout-value {
  font-family: 'JetBrains Mono', monospace;
  font-size: 36px;
  font-weight: 700;
  color: #ef4444;
}

.narrowing-callout-desc {
