+", "+.narrowing-callout {", "+  text-align: center;", "+  padding: 20px 28px;", "+  background: rgba(15,23,42,0.5);", "+  border-radius: 12px;", "+  border: 1px solid rgba(239,68,68,0.2);", "+}", "+", "+.narrowing-callout-label {", "+  font-size: 10px;", "+  font-weight: 600;", "+  text-transform: uppercase;", "+  letter-spacing: 1.5px;", "+  color: #64748b;", "+  margin-bottom: 6px;", "+}", "+", "+.narrowing-callout-value {", "+  font-family: 'JetBrains Mono', monospace;", "+  font-size: 36px;", "+  font-weight: 700;", "+  color: #ef4444;", "+}", "+", "+.narrowing-callout-desc {", "+  font-size: 10.5px;", "+  color: #94a3b8;", "+  margin-top: 4px;", "+}", "+", "+/* ── FOOTER ── */", "+.footer {", "+  margin-top: 20px;", "+  padding-top: 16px;", "+  border-top: 1px solid rgba(71,85,105,0.2);", "+  display: flex;", "+  justify-content: space-between;", "+  align-items: center;", "+}", "+", "+.footer-source {", "+  font-size: 10px;", "+  color: #475569;", "+  font-style: italic;", "+}", "+", "+.footer-branding {", "+  font-size: 10px;", "+  color: #475569;", "+  letter-spacing: 1px;", "+  text-transform: uppercase;", "+}", "+", "+/* ── POPULATION HIGHLIGHT BOX ── */", "+.pop-highlight {", "+  grid-column: 1 / -1;", "+  background: linear-gradient(135deg, rgba(239,68,68,0.08), rgba(30,41,59,0.5));", "+  border: 1px solid rgba(239,68,68,0.2);", "+  border-radius: 14px;", "+  padding: 18px 28px;", "+  display: flex;", "+  align-items: center;", "+  gap: 24px;", "+}", "+", "+.pop-highlight-value {", "+  font-family: 'JetBrains Mono', monospace;", "+  font-size: 42px;", "+  font-weight: 700;", "+  color: #ef4444;", "+  white-space: nowrap;", "+  line-height: 1;", "+}", "+", "+.pop-highlight-unit {", "+  font-size: 18px;", "+  color: #94a3b8;", "+  font-weight: 400;", "+}", "+", "+.pop-highlight-text {", "+  font-size: 13px;", "+  color: #cbd5e1;", "+  line-height: 1.5;", "+}", "+", "+.pop-highlight-text strong {", "+  color: #fbbf24;", "+}", " </style>", " </head>", " <body>", "-<div id="container"></div>", "-<script src="/app/vendor/infographic.min.js"></script>", "+<div class="poster">", "+", "+  <!-- HEADER -->", "+  <div class="header">", "+    <div class="header-badge">IPCC Sixth Assessment Report &middot; 2023</div>", "+    <h1>Climate Change 2023: <span>Key Findings</span></h1>", "+    <p class="subtitle">A synthesis of the most critical findings from the IPCC AR6 cycle — the most comprehensive scientific assessment of climate change to date. Human-caused climate change is already affecting every region on Earth.</p>", "+  </div>", "+", "+  <!-- SEVEN HEADLINE METRICS -->", "+  <div class="metrics-section">", "+    <div class="section-label">&#9632; Seven Headline Metrics</div>", "+    <div class="metrics-grid">", "+      <div class="metric-card">", "+        <div class="metric-value">+1.1°C</div>", "+        <div class="metric-unit">Temperature</div>", "+        <div class="metric-label">Global surface warming<br>2011–2020 vs 1850–1900</div>", "+      </div>", "+      <div class="metric-card">", "+        <div class="metric-value">410</div>", "+        <div class="metric-unit">ppm CO₂</div>", "+        <div class="metric-label">Highest concentration<br>in 2 million years (2019)</div>", "+      </div>", "+      <div class="metric-card">", "+        <div class="metric-value">~59</div>", "+        <div class="metric-unit">GtCO₂e</div>", "+        <div class="metric-label">Global greenhouse gas<br>emissions in 2019</div>", "+      </div>", "+      <div class="metric-card">", "+        <div class="metric-value">~500</div>", "+        <div class="metric-unit">GtCO₂</div>", "+        <div class="metric-label">Remaining carbon budget<br>for 1.5°C (50% chance)</div>", "+      </div>", "+      <div class="metric-card highlight">", "+        <div class="metric-value">43%</div>", "+        <div class="metric-unit">Reduction</div>", "+        <div class="metric-label">Required GHG cut by 2030<br>for 1.5°C pathway</div>", "+      </div>", "+      <div class="metric-card">", "+        <div class="metric-value">0.20m</div>", "+        <div class="metric-unit">Sea Level</div>", "+        <div class="metric-label">Global mean rise<br>1901–2018</div>", "+      </div>", "+      <div class="metric-card highlight">", "+        <div class="metric-value">3.3–3.6B</div>", "+        <div class="metric-unit">People</div>", "+        <div class="metric-label">Highly vulnerable to<br>climate hazards</div>", "+      </div>", "+    </div>", "+  </div>", "+", "+  <!-- HIGHLIGHT BANNER -->", "+  <div class="pop-highlight">", "+    <div>", "+      <div class="pop-highlight-value">3.3–3.6 <span class="pop-highlight-unit">billion</span></div>", "+    </div>", "+    <div class="pop-highlight-text">", "+      people live in contexts <strong>highly vulnerable to climate change</strong>. Climate hazards increasingly interact with poverty, inequality, and ecosystem degradation to produce <strong>cascading and compounding risks</strong> affecting food security, water access, health, and biodiversity worldwide.", "+    </div>", "+  </div>", "+", "+  <!-- MAIN CONTENT GRID -->", "+  <div class="content-area" style="margin-top: 20px;">", "+", "+    <!-- SECTION 1: OBSERVED CHANGES -->", "+    <div class="section observed">", "+      <div class="section-header">", "+        <div class="section-number">1</div>", "+        <div class="section-title">Observed Changes</div>", "+      </div>", "+      <div class="section-body">", "+        Every region has experienced increases in frequency and intensity of extreme weather events — heatwaves, heavy precipitation, droughts, and tropical cyclones — with clear attribution to human influence.", "+      </div>", "+      <div class="indicator-table">", "+        <div class="indicator-row">", "+          <div class="indicator-dot" style="background:#fbbf24"></div>", "+          <div class="indicator-name">Global surface temperature rise</div>", "+          <div class="indicator-val">+1.1°C</div>", "+        </div>", "+        <div class="indicator-row">", "+          <div class="indicator-dot" style="background:#fb923c"></div>", "+          <div class="indicator-name">Atmospheric CO₂ (2019)</div>", "+          <div class="indicator-val">410 ppm</div>", "+        </div>", "+        <div class="indicator-row">", "+          <div class="indicator-dot" style="background:#f97316"></div>", "+          <div class="indicator-name">Global GHG emissions (2019)</div>", "+          <div class="indicator-val">~59 GtCO₂e</div>", "+        </div>", "+        <div class="indicator-row">", "+          <div class="indicator-dot" style="background:#ea580c"></div>", "+          <div class="indicator-name">Sea level rise (1901–2018)</div>", "+          <div class="indicator-val">~0.20 m</div>", "+        </div>", "+        <div class="indicator-row">", "+          <div class="indicator-dot" style="background:#ef4444"></div>", "+          <div class="indicator-name">Arctic sea ice decline (Sep)</div>", "+          <div class="indicator-val">~40%</div>", "+        </div>", "+      </div>", "+    </div>", "+", "+    <!-- SECTION 2: FUTURE PROJECTIONS -->", "+    <div class="section projections">", "+      <div class="section-header">", "+        <div class="section-number">2</div>", "+        <div class="section-title">Future Projections (SSP Scenarios)</div>", "+      </div>", "+      <div class="section-body">", "+        Temperature trajectories diverge sharply depending on emissions pathway. Under the highest scenario, warming could exceed 4.4°C by 2100.", "+      </div>", "+      <div class="ssp-chart">", "+        <div class="ssp-row">", "+          <div class="ssp-label">SSP1-1.9</div>", "+          <div class="ssp-bar-track">", "+            <div class="ssp-bar" style="width:31.8%; background: linear-gradient(90deg, #14b8a6, #0d9488);">", "+              <span class="ssp-temp">1.4°C</span>", "+            </div>", "+          </div>", "+        </div>", "+        <div class="ssp-row">", "+          <div class="ssp-label">SSP1-2.6</div>", "+          <div class="ssp-bar-track">", "+            <div class="ssp-bar" style="width:40.9%; background: linear-gradient(90deg, #3b82f6, #2563eb);">", "+              <span class="ssp-temp">1.8°C</span>", "+            </div>", "+          </div>", "+        </div>", "+        <div class="ssp-row">", "+          <div class="ssp-label">SSP2-4.5</div>", "+          <div class="ssp-bar-track">", "+            <div class="ssp-bar" style="width:61.4%; background: linear-gradient(90deg, #f59e0b, #d97706);">", "+              <span class="ssp-temp">2.7°C</span>", "+            </div>", "+          </div>", "+        </div>", "+        <div class="ssp-row">", "+          <div class="ssp-label">SSP3-7.0</div>", "+          <div class="ssp-bar-track">", "+            <div class="ssp-bar" style="width:81.8%; background: linear-gradient(90deg, #f97316, #ea580c);">", "+              <span class="ssp-temp">3.6°C</span>", "+            </div>", "+          </div>", "+        </div>", "+        <div class="ssp-row">", "+          <div class="ssp-label">SSP5-8.5</div>", "+          <div class="ssp-bar-track">", "+            <div class="ssp-bar" style="width:100%; background: linear-gradient(90deg, #ef4444, #991b1b);">", "+              <span class="ssp-temp">4.4°C</span>", "+            </div>", "+          </div>", "+        </div>", "+        <div class="ssp-desc">Sea level: 0.28–0.55 m (SSP1-1.9) to 0.63–1.01 m (SSP5-8.5) by 2100</div>", "+      </div>", "+    </div>", "+", "+    <!-- SECTION 3: RISKS & IMPACTS -->", "+    <div class="section risks">", "+      <div class="section-header">", "+        <div class="section-number">3</div>", "+        <div class="section-title">Risks & Cascading Impacts</div>", "+      </div>", "+      <div class="risk-grid">", "+        <div class="risk-item">", "+          <div class="risk-icon">🌾</div>", "+          <div class="risk-title">Food Security</div>", "+          <div class="risk-desc">Crop yield growth slowing; fisheries productivity declining in tropical zones</div>", "+        </div>", "+        <div class="risk-item">", "+          <div class="risk-icon">💧</div>", "+          <div class="risk-title">Water Stress</div>", "+          <div class="risk-desc">Over half the world faces severe water scarcity for ≥1 month per year</div>", "+        </div>", "+        <div class="risk-item">", "+          <div class="risk-icon">🏥</div>", "+          <div class="risk-title">Human Health</div>", "+          <div class="risk-desc">Heat-related mortality and vector-borne disease ranges expanding</div>", "+        </div>", "+        <div class="risk-item">", "+          <div class="risk-icon">🦎</div>", "+          <div class="risk-title">Biodiversity</div>", "+          <div class="risk-desc">Up to 14% terrestrial species at very high extinction risk at 1.5°C</div>", "+        </div>", "+      </div>", "+    </div>", "+", "+    <!-- SECTION 4: MITIGATION PATHWAYS -->", "+    <div class="section mitigation">", "+      <div class="section-header">", "+        <div class="section-number">4</div>", "+        <div class="section-title">Mitigation & Adaptation Pathways</div>", "+      </div>", "+      <div class="pathway-compare">", "+        <div class="pathway-box target-15">", "+          <div class="pathway-target">1.5°C</div>", "+          <div class="pathway-label">Target Pathway</div>", "+          <div class="pathway-stat">", "+            <span class="pathway-stat-label">By 2030</span>", "+            <span class="pathway-stat-value" style="color:#14b8a6">−43%</span>", "+          </div>", "+          <div class="pathway-stat">", "+            <span class="pathway-stat-label">Net Zero CO₂</span>", "+            <span class="pathway-stat-value">~2050</span>", "+          </div>", "+          <div class="pathway-stat">", "+            <span class="pathway-stat-label">Carbon Budget</span>", "+            <span class="pathway-stat-value">~500 Gt</span>", "+          </div>", "+        </div>", "+        <div class="pathway-box target-2">", "+          <div class="pathway-target">2.0°C</div>", "+          <div class="pathway-label">Target Pathway</div>", "+          <div class="pathway-stat">", "+            <span class="pathway-stat-label">By 2030</span>", "+            <span class="pathway-stat-value" style="color:#3b82f6">−27%</span>", "+          </div>", "+          <div class="pathway-stat">", "+            <span class="pathway-stat-label">Net Zero CO₂</span>", "+            <span class="pathway-stat-value">~2070</span>", "+          </div>", "+          <div class="pathway-stat">", "+            <span class="pathway-stat-label">Carbon Budget</span>", "+            <span class="pathway-stat-value">~1150 Gt</span>", "+          </div>", "+        </div>", "+      </div>", "+      <div class="levers-list">", "+        <div class="lever-item"><div class="lever-dot"></div>Rapid decarbonization of energy systems</div>", "+        <div class="lever-item"><div class="lever-dot"></div>Electrification of transport</div>", "+        <div class="lever-item"><div class="lever-dot"></div>Demand-side efficiency improvements</div>", "+        <div class="lever-item"><div class="lever-dot"></div>Protection &amp; restoration of carbon sinks</div>", "+      </div>", "+    </div>", "+", "+    <!-- SECTION 5: NARROWING WINDOW -->", "+    <div class="narrowing-window">", "+      <div class="narrowing-header">", "+        <div class="narrowing-number">5</div>", "+        <div class="narrowing-title">The Narrowing Window for Action</div>", "+      </div>", "+      <div class="narrowing-content">", "+        <div class="narrowing-text">", "+          The choices made <strong>in this decade</strong> will determine whether warming can be held to 1.5°C or 2°C. Delayed action increases costs, locks in high-carbon infrastructure, and reduces the feasibility of limiting warming. Climate finance flows remain <strong>insufficient — falling short by a factor of 3 to 6</strong> for adaptation alone. Immediate, deep, and sustained emissions reductions across all sectors are essential to secure a liveable and sustainable future for all.", "+        </div>", "+        <div class="narrowing-callout">", "+          <div class="narrowing-callout-label">Climate Finance Gap</div>", "+          <div class="narrowing-callout-value">3–6×</div>", "+          <div class="narrowing-callout-desc">Shortfall for adaptation needs</div>", "+        </div>", "+      </div>", "+    </div>", "+", "+  </div>", "+", "+  <!-- FOOTER -->", "+  <div class="footer">", "+    <div class="footer-source">Source: IPCC, 2023. AR6 Synthesis Report: Climate Change 2023. Intergovernmental Panel on Climate Change.</div>", "+    <div class="footer-branding">Climate Science Conference 2023</div>", "+  </div>", "+", "+</div>", "+", " <script>", "-const syntax = `infographic list-waterfall-badge-card", "-data", "-  title Climate Change 2023 — IPCC AR6 Synthesis", "-  desc Seven headline metrics from the IPCC Sixth Assessment Synthesis Report (2023). The evidence is unequivocal, impacts are accelerating, and the window for meaningful action is rapidly closing.", "-  lists", "-    - label Global Surface Temperature Rise", "-      value 1.1", "-      desc Degrees Celsius above the 1850–1900 pre-industrial baseline, measured across 2011–2020. Human influence is the dominant driver.", "-      icon thermometer", "-    - label Atmospheric CO2 Concentration", "-      value 410", "-      desc Parts per million in 2019 — the highest level in at least 2 million years, driven by fossil fuel combustion and land-use change.", "-      icon cloud", "-    - label Global GHG Emissions", "-      value 59", "-      desc Gigatonnes of CO2-equivalent emitted in 2019 across all sectors, with energy and industry as the largest contributors.", "-      icon factory", "-    - label Remaining Carbon Budget for 1.5°C", "-      value 500", "-      desc Gi