<html lang="en">
<head>
<meta charset="utf-8" />
<title>IPCC AR6 Synthesis - Infographic</title>
<style>
  html, body { margin: 0; padding: 0; background: #0b1220; }
  #container { width: 1400px; height: 1980px; }
</style>
</head>
<body>
<div id="container"></div>
<script src="/app/vendor/infographic.min.js"></script>
<script>
const syntax = `infographic list-waterfall-badge-card
data
  title Climate Change 2023 — IPCC AR6 Synthesis
  desc Seven headline metrics from the IPCC Sixth Assessment Synthesis Report (2023). The evidence is unequivocal, impacts are accelerating, and the window for meaningful action is rapidly closing.
  lists
    - label Global Surface Temperature Rise
      value 1.1
      desc Degrees Celsius above the 1850–1900 pre-industrial baseline, measured across 2011–2020. Human influence is the dominant driver.
      icon thermometer
    - label Atmospheric CO2 Concentration
      value 410
      desc Parts per million in 2019 — the highest level in at least 2 million years, driven by fossil fuel combustion and land-use change.
      icon cloud
    - label Global GHG Emissions
      value 59
      desc Gigatonnes of CO2-equivalent emitted in 2019 across all sectors, with energy and industry as the largest contributors.
      icon factory
    - label Remaining Carbon Budget for 1.5°C
      value 500
      desc Gigatonnes of CO2 remaining from 2020 for a 50% chance of limiting warming to 1.5°C — a budget being depleted every year.
      icon hourglass
    - label Required GHG Reduction by 2030
      value 43
      desc Percent reduction below 2019 levels required this decade to stay on a 1.5°C pathway with no or limited overshoot; net zero CO2 by ~2050.
      icon trending down
    - label Sea Level Rise (1901–2018)
      value 0.20
      desc Metres of observed global mean sea level rise since 1901. Rise will continue for centuries to millennia regardless of pathway.
      icon water
    - label Population Exposed to Severe Climate Hazards
      value 3.5
      desc Billion people living in contexts highly vulnerable to climate change — compounded by poverty, inequality, and ecosystem degradation.
      icon users
theme
  palette #f59e0b #fb923c #ef4444 #dc2626 #991b1b #b45309 #7c2d12
`;
const infographic = new AntVInfographic.Infographic({
  container: '#container',
  width: '100%',
  height: '100%',
});
window.__ready = false;
(async () => {
  try {
    await infographic.render(syntax);
    if (document.fonts && document.fonts.ready) {
      await document.fonts.ready;
      await infographic.render(syntax);
    }
  } catch (e) { console.error(e); }
  window.__ready = true;
})();
</script>
</body>
</html>
